begin;
create type public.transaction_type as enum('BUY','SELL','ADJUSTMENT');
create type public.transaction_source as enum('MANUAL','CSV_IMPORT','BROKER_IMPORT');
create type public.nav_freshness as enum('FRESH','STALE','MISSING','FX_REQUIRED');
create table public.portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,base_currency char(3) not null default 'NOK' check(base_currency~'^[A-Z]{3}$'),portfolio_proposal_id uuid references public.portfolio_proposals(id) on delete set null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.transactions(id uuid primary key default gen_random_uuid(),client_transaction_id text not null,portfolio_id uuid not null references public.portfolios(id) on delete cascade,fund_id uuid not null references public.funds(id) on delete restrict,transaction_type public.transaction_type not null,trade_date date not null,settlement_date date,amount numeric(20,8),nav numeric(20,8),units numeric(24,10) not null,currency char(3) not null check(currency~'^[A-Z]{3}$'),fees numeric(20,8) not null default 0 check(fees>=0),source public.transaction_source not null default 'MANUAL',notes text,correction_of_id uuid references public.transactions(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(portfolio_id,client_transaction_id),check(nav is null or nav>0),check(transaction_type='ADJUSTMENT' or units>0),check(transaction_type='ADJUSTMENT' or amount>0));
create table public.transaction_revisions(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.transactions(id) on delete restrict,revision_number integer not null,previous_data jsonb not null,replacement_transaction_id uuid references public.transactions(id) on delete restrict,reason text not null,created_at timestamptz not null default now(),unique(transaction_id,revision_number));
create table public.portfolio_snapshots(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.portfolios(id) on delete cascade,snapshot_date date not null,total_invested numeric(20,8) not null,market_value numeric(20,8),unrealized_gain_loss numeric(20,8),realized_gain_loss numeric(20,8) not null,total_return_percent numeric(16,10),data_version jsonb not null,data_version_hash text not null,created_at timestamptz not null default now(),unique(portfolio_id,snapshot_date,data_version_hash));
create table public.portfolio_position_snapshots(id uuid primary key default gen_random_uuid(),portfolio_snapshot_id uuid not null references public.portfolio_snapshots(id) on delete cascade,fund_id uuid not null references public.funds(id) on delete restrict,units numeric(24,10) not null,nav numeric(20,8),nav_date date,nav_freshness public.nav_freshness not null,market_value numeric(20,8),cost_basis numeric(20,8) not null,unrealized_gain_loss numeric(20,8),actual_weight numeric(12,10),created_at timestamptz not null default now(),unique(portfolio_snapshot_id,fund_id));
create trigger portfolios_set_updated_at before update on public.portfolios for each row execute function public.set_updated_at();create trigger transactions_set_updated_at before update on public.transactions for each row execute function public.set_updated_at();
create index transactions_portfolio_date_idx on public.transactions(portfolio_id,trade_date,id);create index portfolio_snapshots_portfolio_date_idx on public.portfolio_snapshots(portfolio_id,snapshot_date desc);
alter table public.portfolios enable row level security;alter table public.transactions enable row level security;alter table public.transaction_revisions enable row level security;alter table public.portfolio_snapshots enable row level security;alter table public.portfolio_position_snapshots enable row level security;
commit;
